#![cfg_attr(not(debug_assertions), windows_subsystem = "windows")]
use std::{fs,io::Cursor,path::{Path,PathBuf},sync::Mutex,time::{SystemTime,UNIX_EPOCH}};
use serde::{Deserialize,Serialize};
use tauri::State;
use base64::Engine;
use lopdf::{dictionary,Document,Object,Stream};
use lopdf::content::{Content,Operation};
use svgtypes::{PathParser,PathSegment};
use tauri::Manager;
use windows_core::Interface;
use std::os::windows::process::CommandExt;

#[derive(Default)]
struct Session { folder:Mutex<Option<PathBuf>>,print_data:Mutex<String> }

#[derive(Deserialize)]
struct Scene { width:f64,height:f64,elements:Vec<Shape>,title:Option<String> }

#[derive(Deserialize)]
#[serde(tag="type")]
enum Shape {
    #[serde(rename="rect")] Rect{x:f64,y:f64,w:f64,h:f64,fill:String},
    #[serde(rename="path")] Path{d:String,fill:String},
    #[serde(rename="border")] Border{x:f64,y:f64,w:f64,h:f64,r:f64,stroke:String,#[serde(rename="strokeWidth")] stroke_width:f64},
    #[serde(rename="image")] Image{x:f64,y:f64,w:f64,h:f64,href:String},
}

#[derive(Serialize)]
struct Written { file:String,bytes:usize }

fn safe(s:&str)->String { let v:String=s.chars().filter(|c|!c.is_control()).map(|c|if "<>:\"/\\|?*".contains(c){'_'}else{c}).take(100).collect();let v=v.trim_matches([' ','.']);if v.is_empty(){"Etichette".into()}else{v.into()} }
fn err(e:impl std::fmt::Display)->String {e.to_string()}
fn number(v:f64)->Object {Object::Real(v as f32)}
fn operation(name:&str,values:&[f64])->Operation {Operation::new(name,values.iter().map(|v|number(*v)).collect())}
fn color(hex:&str)->Result<Vec<f64>,String>{let h=hex.strip_prefix('#').ok_or("Colore non valido")?;if h.len()!=6{return Err("Colore non valido".into());}let v=u32::from_str_radix(h,16).map_err(err)?;Ok(vec![((v>>16)&255) as f64/255.,((v>>8)&255)as f64/255.,(v&255)as f64/255.])}
fn valid_scene(s:&Scene)->Result<(),String>{if !s.width.is_finite()||!s.height.is_finite()||s.width<=0.||s.height<=0.||s.width>1_000_000.||s.height>1_000_000.||s.elements.len()>2_000_000{return Err("Dimensioni o contenuto della pagina non validi".into());}Ok(())}
fn target(state:&Session,name:&str)->Result<PathBuf,String>{if name.contains(['/', '\\'])||name=="."||name==".."||name.is_empty(){return Err("Nome file non valido".into());}let folder=state.folder.lock().map_err(err)?.clone().ok_or("Scegliere una cartella di esportazione")?;Ok(folder.join(safe(name)))}

#[tauri::command]
fn begin_export(parent:String,name:String,format:String,state:State<Session>)->Result<String,String>{let parent=PathBuf::from(parent);if !parent.is_dir(){return Err("Cartella non valida".into());}let stamp=SystemTime::now().duration_since(UNIX_EPOCH).map_err(err)?.as_millis();let folder=parent.join(format!("{}_{}_{}",safe(&name),safe(&format).to_uppercase(),stamp));fs::create_dir(&folder).map_err(err)?;*state.folder.lock().map_err(err)?=Some(folder.clone());Ok(folder.to_string_lossy().into())}

#[tauri::command]
async fn write_text(name:String,text:String,state:State<'_,Session>)->Result<Written,String>{if text.len()>300_000_000{return Err("File troppo grande".into());}let file=target(&state,&name)?;fs::write(&file,text.as_bytes()).map_err(err)?;Ok(Written{file:file.to_string_lossy().into(),bytes:text.len()})}

#[tauri::command]
async fn save_project(file:String,text:String)->Result<(),String>{if text.len()>20_000_000||!file.to_lowercase().ends_with(".json"){return Err("Progetto non valido".into());}fs::write(file,text).map_err(err)}

#[tauri::command]
async fn read_text(file:String)->Result<String,String>{let p=Path::new(&file);let ext=p.extension().and_then(|s|s.to_str()).unwrap_or("").to_lowercase();if !["json","csv","tsv","txt"].contains(&ext.as_str()){return Err("Tipo file non consentito".into());}if fs::metadata(p).map_err(err)?.len()>20_000_000{return Err("File troppo grande".into());}fs::read_to_string(p).map_err(err)}

#[tauri::command]
async fn import_logo(file:String)->Result<String,String>{let data=fs::read(&file).map_err(err)?;if data.len()>10_000_000{return Err("Logo troppo grande: massimo 10 MB".into());}let img=if file.to_lowercase().ends_with(".svg"){render(&String::from_utf8(data).map_err(err)?,200.)?}else{image::load_from_memory(&data).map_err(err)?};let img=img.thumbnail(1800,1800);let mut buf=Cursor::new(Vec::new());img.write_to(&mut buf,image::ImageFormat::Png).map_err(err)?;Ok(format!("data:image/png;base64,{}",base64::engine::general_purpose::STANDARD.encode(buf.into_inner())))}

fn render(svg:&str,dpi:f64)->Result<image::DynamicImage,String>{if ![203.,300.,600.,1200.,200.].contains(&dpi){return Err("DPI non validi".into());}let tree=resvg::usvg::Tree::from_data(svg.as_bytes(),&resvg::usvg::Options::default()).map_err(err)?;let scale=(dpi/96.)as f32;let w=(tree.size().width()*scale).ceil()as u32;let h=(tree.size().height()*scale).ceil()as u32;if w>30000||h>30000||w as u64*h as u64>40_000_000{return Err("Immagine troppo lunga o grande. Usare etichette singole, fogli o meno etichette per file. Per bobine lunghe scegliere SVG o PDF.".into());}let mut pix=resvg::tiny_skia::Pixmap::new(w,h).ok_or("Memoria insufficiente per l’immagine")?;resvg::render(&tree,resvg::tiny_skia::Transform::from_scale(scale,scale),&mut pix.as_mut());let mut bytes=pix.data().to_vec();for pixel in bytes.chunks_exact_mut(4){let a=pixel[3]as u32;if a>0&&a<255{for c in &mut pixel[..3]{*c=((*c as u32*255+a/2)/a).min(255)as u8;}}}Ok(image::DynamicImage::ImageRgba8(image::RgbaImage::from_raw(w,h,bytes).ok_or("Immagine non valida")?))}

fn white(img:image::DynamicImage)->image::DynamicImage{let mut rgb=image::RgbImage::new(img.width(),img.height());for (x,y,p)in img.to_rgba8().enumerate_pixels(){let a=p[3]as u32;rgb.put_pixel(x,y,image::Rgb([((p[0]as u32*a+255*(255-a))/255)as u8,((p[1]as u32*a+255*(255-a))/255)as u8,((p[2]as u32*a+255*(255-a))/255)as u8]));}image::DynamicImage::ImageRgb8(rgb)}

#[tauri::command]
async fn import_design(file:String)->Result<serde_json::Value,String>{let p=Path::new(&file);let data=fs::read(p).map_err(err)?;if data.len()>50_000_000{return Err("File troppo grande: massimo 50 MB".into());}let name=p.file_name().unwrap_or_default().to_string_lossy().to_string();let ext=p.extension().and_then(|s|s.to_str()).unwrap_or("").to_lowercase();if ext=="json"{return Ok(serde_json::json!({"kind":"project","text":String::from_utf8(data).map_err(err)?,"name":name}));}if data.starts_with(b"%PDF-"){return Ok(serde_json::json!({"kind":"pdf","data":base64::engine::general_purpose::STANDARD.encode(data),"name":name}));}let(mut width_mm,mut height_mm)=(None,None);let img=if ext=="svg"{let mut options=resvg::usvg::Options::default();options.fontdb_mut().load_system_fonts();let tree=resvg::usvg::Tree::from_data(&data,&options).map_err(err)?;width_mm=Some(tree.size().width()as f64*25.4/96.);height_mm=Some(tree.size().height()as f64*25.4/96.);let scale=(600./96.)as f32;let w=(tree.size().width()*scale).ceil()as u32;let h=(tree.size().height()*scale).ceil()as u32;if w as u64*h as u64>30_000_000||w>20000||h>20000{return Err("Design troppo grande: importare una singola etichetta o un singolo foglio".into());}let mut pix=resvg::tiny_skia::Pixmap::new(w,h).ok_or("Memoria insufficiente")?;pix.fill(resvg::tiny_skia::Color::WHITE);resvg::render(&tree,resvg::tiny_skia::Transform::from_scale(scale,scale),&mut pix.as_mut());image::DynamicImage::ImageRgba8(image::RgbaImage::from_raw(w,h,pix.data().to_vec()).ok_or("Immagine non valida")?)}else{let img=image::load_from_memory(&data).map_err(err)?;if img.width()as u64*img.height()as u64>40_000_000{return Err("Immagine troppo grande".into());}img};let pixels=(img.width(),img.height());let mut output=Cursor::new(Vec::new());img.write_to(&mut output,image::ImageFormat::Png).map_err(err)?;Ok(serde_json::json!({"kind":"image","name":name,"data":format!("data:image/png;base64,{}",base64::engine::general_purpose::STANDARD.encode(output.into_inner())),"width":pixels.0,"height":pixels.1,"widthMM":width_mm,"heightMM":height_mm}))}

#[tauri::command]
async fn list_printers()->Result<serde_json::Value,String>{tauri::async_runtime::spawn_blocking(||{let output=std::process::Command::new("powershell.exe").args(["-NoProfile","-NonInteractive","-Command","[Console]::OutputEncoding=[Text.UTF8Encoding]::new(); @(Get-CimInstance Win32_Printer | Select-Object Name,DriverName,PortName,Default,WorkOffline) | ConvertTo-Json -Compress"]).creation_flags(0x08000000).output().map_err(err)?;if !output.status.success(){return Err("Impossibile leggere le stampanti. Verificare il servizio di stampa Windows".into());}let text=String::from_utf8_lossy(&output.stdout);if text.trim().is_empty(){return Ok(serde_json::json!([]));}let value:serde_json::Value=serde_json::from_str(text.trim_start_matches('\u{feff}')).map_err(err)?;Ok(if value.is_array(){value}else{serde_json::json!([value])})}).await.map_err(err)?}

#[tauri::command]
async fn printer_settings()->Result<(),String>{std::process::Command::new("explorer.exe").arg("ms-settings:printers").creation_flags(0x08000000).spawn().map_err(err)?;Ok(())}

#[tauri::command]
async fn prepare_print(html:String,width:f64,height:f64,app:tauri::AppHandle,state:State<'_,Session>)->Result<(),String>{if html.len()>250_000_000||width<5.||height<5.{return Err("Documento di stampa non valido".into());}*state.print_data.lock().map_err(err)?=serde_json::json!({"html":html,"width":width,"height":height}).to_string();if let Some(old)=app.get_webview_window("print-preview"){old.close().map_err(err)?;}tauri::WebviewWindowBuilder::new(&app,"print-preview",tauri::WebviewUrl::App("print.html".into())).title("Anteprima e stampa - Etichette Studio").inner_size(1000.,800.).build().map_err(err)?;Ok(())}

#[tauri::command]
fn get_print_data(state:State<Session>)->Result<String,String>{Ok(state.print_data.lock().map_err(err)?.clone())}

#[tauri::command]
async fn show_print_ui(window:tauri::WebviewWindow)->Result<(),String>{let(tx,rx)=std::sync::mpsc::channel();window.with_webview(move|view|{let result=(||unsafe{let core=view.controller().CoreWebView2().map_err(err)?;let print: webview2_com::Microsoft::Web::WebView2::Win32::ICoreWebView2_16=core.cast().map_err(err)?;print.ShowPrintUI(webview2_com::Microsoft::Web::WebView2::Win32::COREWEBVIEW2_PRINT_DIALOG_KIND_SYSTEM).map_err(err)})();let _=tx.send(result);}).map_err(err)?;rx.recv().map_err(err)?}

fn encode_image(img:image::DynamicImage,format:&str,dpi:f64,quality:u8)->Result<Vec<u8>,String>{let img=if ["jpg","bmp","tiff"].contains(&format){white(img)}else{img};let mut buf=Cursor::new(Vec::new());match format{"png"=>{let mut encoder=png::Encoder::new(&mut buf,img.width(),img.height());encoder.set_color(png::ColorType::Rgba);encoder.set_depth(png::BitDepth::Eight);encoder.set_pixel_dims(Some(png::PixelDimensions{xppu:(dpi/0.0254).round()as u32,yppu:(dpi/0.0254).round()as u32,unit:png::Unit::Meter}));let mut writer=encoder.write_header().map_err(err)?;writer.write_image_data(img.to_rgba8().as_raw()).map_err(err)?;},"jpg"=>{let mut encoder=image::codecs::jpeg::JpegEncoder::new_with_quality(&mut buf,quality.clamp(50,100));encoder.set_pixel_density(image::codecs::jpeg::PixelDensity::dpi(dpi as u16));encoder.encode_image(&img).map_err(err)?;},"tiff"=>{let rgb=img.to_rgb8();let mut encoder=tiff::encoder::TiffEncoder::new(&mut buf).map_err(err)?;let mut picture=encoder.new_image::<tiff::encoder::colortype::RGB8>(img.width(),img.height()).map_err(err)?;picture.resolution(tiff::tags::ResolutionUnit::Inch,tiff::encoder::Rational{n:dpi as u32,d:1});picture.write_data(rgb.as_raw()).map_err(err)?;},_=>{let fmt=match format{"webp"=>image::ImageFormat::WebP,"bmp"=>image::ImageFormat::Bmp,"gif"=>image::ImageFormat::Gif,"avif"=>image::ImageFormat::Avif,_=>return Err("Formato immagine non valido".into())};img.write_to(&mut buf,fmt).map_err(err)?;}}let mut data=buf.into_inner();if format=="bmp"&&data.len()>46{let ppm=((dpi/0.0254).round()as i32).to_le_bytes();data[38..42].copy_from_slice(&ppm);data[42..46].copy_from_slice(&ppm);}Ok(data)}

#[tauri::command]
async fn write_image(name:String,svg:String,format:String,dpi:f64,quality:u8,state:State<'_,Session>)->Result<Written,String>{let file=target(&state,&name)?;tauri::async_runtime::spawn_blocking(move||{let data=encode_image(render(&svg,dpi)?,&format,dpi,quality)?;fs::write(&file,&data).map_err(err)?;Ok(Written{file:file.to_string_lossy().into(),bytes:data.len()})}).await.map_err(err)?}

fn path_ops(d:&str,ops:&mut Vec<Operation>)->Result<(),String>{let(mut x,mut y,mut sx,mut sy)=(0.,0.,0.,0.);let(mut cx,mut cy,mut qx,mut qy)=(0.,0.,0.,0.);let mut last='M';for s in PathParser::from(d){match s.map_err(err)?{PathSegment::MoveTo{abs,x:nx,y:ny}=>{x=if abs{nx}else{x+nx};y=if abs{ny}else{y+ny};sx=x;sy=y;ops.push(operation("m",&[x,y]));last='M';},PathSegment::LineTo{abs,x:nx,y:ny}=>{x=if abs{nx}else{x+nx};y=if abs{ny}else{y+ny};ops.push(operation("l",&[x,y]));last='L';},PathSegment::HorizontalLineTo{abs,x:nx}=>{x=if abs{nx}else{x+nx};ops.push(operation("l",&[x,y]));last='L';},PathSegment::VerticalLineTo{abs,y:ny}=>{y=if abs{ny}else{y+ny};ops.push(operation("l",&[x,y]));last='L';},PathSegment::CurveTo{abs,x1,y1,x2,y2,x:nx,y:ny}=>{let(a,b,c,d,e,f)=if abs{(x1,y1,x2,y2,nx,ny)}else{(x+x1,y+y1,x+x2,y+y2,x+nx,y+ny)};ops.push(operation("c",&[a,b,c,d,e,f]));cx=c;cy=d;x=e;y=f;last='C';},PathSegment::SmoothCurveTo{abs,x2,y2,x:nx,y:ny}=>{let(a,b)=if last=='C'{(2.*x-cx,2.*y-cy)}else{(x,y)};let(c,d,e,f)=if abs{(x2,y2,nx,ny)}else{(x+x2,y+y2,x+nx,y+ny)};ops.push(operation("c",&[a,b,c,d,e,f]));cx=c;cy=d;x=e;y=f;last='C';},PathSegment::Quadratic{abs,x1,y1,x:nx,y:ny}=>{let(a,b,e,f)=if abs{(x1,y1,nx,ny)}else{(x+x1,y+y1,x+nx,y+ny)};ops.push(operation("c",&[x+2.*(a-x)/3.,y+2.*(b-y)/3.,e+2.*(a-e)/3.,f+2.*(b-f)/3.,e,f]));qx=a;qy=b;x=e;y=f;last='Q';},PathSegment::SmoothQuadratic{abs,x:nx,y:ny}=>{let(a,b)=if last=='Q'{(2.*x-qx,2.*y-qy)}else{(x,y)};let(e,f)=if abs{(nx,ny)}else{(x+nx,y+ny)};ops.push(operation("c",&[x+2.*(a-x)/3.,y+2.*(b-y)/3.,e+2.*(a-e)/3.,f+2.*(b-f)/3.,e,f]));qx=a;qy=b;x=e;y=f;last='Q';},PathSegment::ClosePath{..}=>{ops.push(operation("h",&[]));x=sx;y=sy;last='Z';},PathSegment::EllipticalArc{..}=>return Err("Arco non normalizzato nel tracciato".into()),}}Ok(())}

fn build_pdf(scene:&Scene)->Result<Vec<u8>,String>{valid_scene(scene)?;let mut doc=Document::with_version("1.7");let pages_id=doc.new_object_id();let unit=(scene.width.max(scene.height)*72./25.4/14000.).ceil().max(1.);let k=72./25.4/unit;let mut ops=vec![operation("q",&[]),operation("cm",&[k,0.,0.,-k,0.,scene.height*k])];let mut images=lopdf::Dictionary::new();let mut count=0;for shape in &scene.elements{match shape{Shape::Rect{x,y,w,h,fill}=>{ops.push(operation("rg",&color(fill)?));ops.push(operation("re",&[*x,*y,*w,*h]));ops.push(operation("f",&[]));},Shape::Path{d,fill}=>{ops.push(operation("rg",&color(fill)?));path_ops(d,&mut ops)?;ops.push(operation("f",&[]));},Shape::Border{x,y,w,h,r,stroke,stroke_width}=>{ops.push(operation("RG",&color(stroke)?));ops.push(operation("w",&[*stroke_width]));let r=r.min(w/2.).min(h/2.).max(0.);if r==0.{ops.push(operation("re",&[*x,*y,*w,*h]));}else{let d=format!("M {} {} H {} Q {} {} {} {} V {} Q {} {} {} {} H {} Q {} {} {} {} V {} Q {} {} {} {} Z",x+r,y,x+w-r,x+w,y,x+w,y+r,y+h-r,x+w,y+h,x+w-r,y+h,x+r,x,y+h,x,y+h-r,y+r,x,y,x+r,y);path_ops(&d,&mut ops)?;}ops.push(operation("S",&[]));},Shape::Image{x,y,w,h,href}=>{let encoded=href.split_once(',').ok_or("Logo non valido")?.1;let data=base64::engine::general_purpose::STANDARD.decode(encoded).map_err(err)?;let img=white(image::load_from_memory(&data).map_err(err)?).to_rgb8();let width=img.width();let height=img.height();let mut image=Stream::new(dictionary!{"Type"=>"XObject","Subtype"=>"Image","Width"=>width as i64,"Height"=>height as i64,"ColorSpace"=>"DeviceRGB","BitsPerComponent"=>8},img.into_raw());image.compress().map_err(err)?;let id=doc.add_object(image);let name=format!("Im{}",count);count+=1;images.set(name.as_bytes(),id);let scale=(w/width as f64).min(h/height as f64);let iw=width as f64*scale;let ih=height as f64*scale;ops.push(operation("q",&[]));ops.push(operation("cm",&[iw,0.,0.,-ih,x+(w-iw)/2.,y+(h-ih)/2.+ih]));ops.push(Operation::new("Do",vec![Object::Name(name.into_bytes())]));ops.push(operation("Q",&[]));}}}ops.push(operation("Q",&[]));let content=Content{operations:ops}.encode().map_err(err)?;let content_id=doc.add_object(Stream::new(dictionary!{},content));let resources_id=doc.add_object(dictionary!{"XObject"=>images});let page_id=doc.add_object(dictionary!{"Type"=>"Page","Parent"=>pages_id,"MediaBox"=>vec![number(0.),number(0.),number(scene.width*k),number(scene.height*k)],"UserUnit"=>number(unit),"Contents"=>content_id,"Resources"=>resources_id});doc.objects.insert(pages_id,dictionary!{"Type"=>"Pages","Kids"=>vec![Object::Reference(page_id)],"Count"=>1}.into());let catalog_id=doc.add_object(dictionary!{"Type"=>"Catalog","Pages"=>pages_id,"ViewerPreferences"=>dictionary!{"PrintScaling"=>"None"}});doc.trailer.set("Root",catalog_id);let info=doc.add_object(dictionary!{"Title"=>Object::string_literal(scene.title.clone().unwrap_or_else(||"Etichette Studio".into())),"Creator"=>Object::string_literal("Etichette Studio - NIS"),"Author"=>Object::string_literal("NIS")});doc.trailer.set("Info",info);doc.compress();let mut output=Vec::new();doc.save_to(&mut output).map_err(err)?;Ok(output)}

#[tauri::command]
async fn write_pdf(name:String,scene:Scene,state:State<'_,Session>)->Result<Written,String>{let file=target(&state,&name)?;tauri::async_runtime::spawn_blocking(move||{let bytes=build_pdf(&scene)?;fs::write(&file,&bytes).map_err(err)?;Ok(Written{file:file.to_string_lossy().into(),bytes:bytes.len()})}).await.map_err(err)?}

#[tauri::command]
async fn write_thermal(name:String,svgs:Vec<String>,format:String,dpi:f64,width:f64,height:f64,gap:f64,state:State<'_,Session>)->Result<Written,String>{let file=target(&state,&name)?;tauri::async_runtime::spawn_blocking(move||{if ![203.,300.,600.].contains(&dpi){return Err("Per i comandi termici usare 203, 300 o 600 dpi".into());}let mut output=Vec::new();for svg in svgs{let img=white(render(&svg,dpi)?).to_luma8();let(w,h)=img.dimensions();let stride=(w as usize+7)/8;let mut bits=vec![0u8;stride*h as usize];for y in 0..h{for x in 0..w{if img.get_pixel(x,y)[0]<128{bits[y as usize*stride+x as usize/8]|=128>>(x%8);}}}match format.as_str(){"zpl"=>{if bits.len()>99999{return Err("Grafica ZPL oltre 99.999 byte: ridurre formato o DPI".into());}let hex:String=bits.iter().map(|v|format!("{:02X}",v)).collect();output.extend(format!("^XA\n^PW{w}\n^LL{h}\n^LH0,0\n^FO0,0^GFA,{0},{0},{stride},{hex}^FS\n^PQ1\n^XZ\n",bits.len()).as_bytes());},"epl"=>{output.extend(format!("N\nq{w}\nQ{h},{}\nGW0,0,{stride},{h},",(gap*dpi/25.4).round()).as_bytes());output.extend(bits.iter().map(|v|255-v));output.extend(b"\nP1\n");},"tspl"=>{output.extend(format!("SIZE {width} mm,{height} mm\r\nGAP {gap} mm,0 mm\r\nDIRECTION 1\r\nCLS\r\nBITMAP 0,0,{stride},{h},0,").as_bytes());output.extend(bits.iter().map(|v|255-v));output.extend(b"\r\nPRINT 1,1\r\n");},_=>return Err("Linguaggio stampante non valido".into())}}let mut destination=fs::OpenOptions::new().create(true).append(true).open(&file).map_err(err)?;std::io::Write::write_all(&mut destination,&output).map_err(err)?;Ok(Written{file:file.to_string_lossy().into(),bytes:output.len()})}).await.map_err(err)?}

fn self_test(file:&str)->Result<(),String>{let file=Path::new(file);let data:serde_json::Value=serde_json::from_str(&fs::read_to_string(file).map_err(err)?).map_err(err)?;let out=file.parent().ok_or("Percorso test non valido")?.join("native-results");fs::create_dir_all(&out).map_err(err)?;for case in data.as_array().ok_or("Test non valido")?{let name=case["name"].as_str().ok_or("Nome test mancante")?;let scene:Scene=serde_json::from_value(case["scene"].clone()).map_err(err)?;fs::write(out.join(format!("{}.pdf",safe(name))),build_pdf(&scene)?).map_err(err)?;if let Some(svg)=case["svg"].as_str(){for fmt in ["png","jpg","tiff","bmp","webp","gif","avif"]{let bytes=encode_image(render(svg,300.)?,fmt,300.,95)?;fs::write(out.join(format!("{}.{}",safe(name),fmt)),bytes).map_err(err)?;}}}fs::write(out.join("OK.txt"),"PDF e immagini generati dal backend Rust").map_err(err)?;Ok(())}

#[tauri::command]
async fn append_text(name:String,text:String,state:State<'_,Session>)->Result<(),String>{let file=target(&state,&name)?;tauri::async_runtime::spawn_blocking(move||{let mut out=fs::OpenOptions::new().append(true).open(file).map_err(err)?;std::io::Write::write_all(&mut out,text.as_bytes()).map_err(err)}).await.map_err(err)?}

fn main(){let args:Vec<String>=std::env::args().collect();if args.len()==3&&args[1]=="--self-test"{if let Err(e)=self_test(&args[2]){let _=fs::write(Path::new(&args[2]).with_extension("error.txt"),e);std::process::exit(1);}return;}tauri::Builder::default().manage(Session::default()).plugin(tauri_plugin_dialog::init()).plugin(tauri_plugin_opener::init()).plugin(tauri_plugin_updater::Builder::new().build()).invoke_handler(tauri::generate_handler![import_design,list_printers,printer_settings,prepare_print,get_print_data,show_print_ui,begin_export,write_text,append_text,write_image,write_pdf,write_thermal,save_project,read_text,import_logo]).run(tauri::generate_context!()).expect("Impossibile avviare Etichette Studio");}
